static void
set_maze_sizes (struct state *st, int width, int height)
{
  st->maze_size_x = width / st->grid_width;
  st->maze_size_y = height / st->grid_height;

  if (st->maze_size_x < 4) st->maze_size_x = 4;
  if (st->maze_size_y < 4) st->maze_size_y = 4;
