}


static unsigned long
maze_draw (Display *dpy, Window window, void *closure)
{
  struct state *st = (struct state *) closure;
  int this_delay = st->solve_delay;

  if (st->eraser || st->erase_window)
    {
      st->erase_window = 0;
      st->eraser = erase_window (st->dpy, st->window, st->eraser);
      if (st->eraser)
        this_delay = 10000;
      else {
        this_delay = 1000000;
        if (this_delay > st->pre_solve_delay)
          this_delay = st->pre_solve_delay;
      }
      goto END;
    }

    if (st->restart || st->stop) goto pop;
    switch (st->state) {
    case 1:
      initialize_maze(st);
      if (st->ifrandom && st->ifinit)
       {
	 int size;
         size = 7 + (random () % 30);
         st->grid_width = st->grid_height = size;
         st->bw = (size > 6 ? 3 : (size-1)/2);
         st->ifinit = 0;
	 st->restart = 1;
       }
      break;
    case 2:
      XClearWindow(st->dpy, st->window);
      draw_maze_border(st);
      break;
    case 3:
      st->this_gen = generator;
      if(st->this_gen<0 || st->this_gen>2)
	st->this_gen = random()%3;

      switch(st->this_gen)
	{
	case 0:
	  create_maze(st);
	  break;
	case 1:
	  alt_create_maze(st);
	  break;
	case 2:
	  set_create_maze(st);
	  break;
	}
      break;
    case 4:
      this_delay = st->pre_solve_delay;
      break;
    case 5:
      if (! solve_maze(st))
        --st->state;  /* stay in state 5 */
      break;
    case 6:
      st->erase_window = 1;
      this_delay = st->post_solve_delay;
      st->state = 0 ;
      st->ifinit = 1;
      break;
    default:
      abort ();
    }
    ++st->state;
  pop:
    if (st->restart)
      {
        XWindowAttributes xgwa;
        int size;

        st->restart = 0;
        st->stop = 0;
        st->state = 1;

        if (st->solve_state && st->solve_state->running)
          st->solve_state->running = 0;

        st->sync_p = ((random() % 4) != 0);

        size = get_integer_resource (st->dpy, "gridSize", "Dimension");
        if (size < 2) size = 7 + (random () % 30);
        st->grid_width = st->grid_height = size;
        st->bw = (size > 6 ? 3 : (size-1)/2);

        XGetWindowAttributes (st->dpy, st->window, &xgwa);
        set_maze_sizes (st, xgwa.width, xgwa.height);
      }

 END:
    return this_delay;
}


static Bool
maze_event (Display *dpy, Window window, void *closure, XEvent *event)
{
  struct state *st = (struct state *) closure;
  if (event->type == ButtonPress)
    {
      switch (event->xbutton.button) 
        {
        case 2:
          st->stop = !st->stop ;
          if (st->state == 5) st->state = 4 ;
          else {
            st->restart = 1;
            st->stop = 0;
          }
          return True;

        default:
          st->restart = 1 ;
          st->stop = 0 ;
          return True;
        }
    }
  else if (event->type == Expose)
    {
      st->restart = 1;
      return False;
    }
  else if (screenhack_event_helper (dpy, window, event))
    {
      st->restart = 1 ;
      st->stop = 0 ;
      return True;
    }
  return False;
}


static void
maze_free (Display *dpy, Window window, void *closure)
{
  struct state *st = (struct state *) closure;
  XFreeGC (dpy, st->gc);
  XFreeGC (dpy, st->cgc);
  XFreeGC (dpy, st->tgc);
  XFreeGC (dpy, st->sgc);
  XFreeGC (dpy, st->ugc);
  XFreeGC (dpy, st->logo_gc);
  XFreeGC (dpy, st->erase_gc);
  if (st->solve_state) free (st->solve_state);
  if (st->logo_map) XFreePixmap (dpy, st->logo_map);
  exit_sets (st);
  free (st);
}

