/* Usage: dump <hack-index> <frames> <out.raw>  (466x466 little-endian RGB565) */
int main(int argc, char **argv) {
  if (argc != 4) {
    fprintf(stderr, "usage: %s <hack-index> <frames> <out.raw>\n", argv[0]);
